document.addEventListener('DOMContentLoaded', function () {
  if (window.innerWidth < 1024) return;
  class V5ScrollProductFeatures1 {
    constructor() {
      this.sectionId = '#v5ScrollProductFeatures1';
      this.v5ScrollProductFeatures1Trigger = null;
      this.scrollTimeLine();
      this.observeFunc();
    }

    observeFunc(){
      const self = this;
      // 橱窗版块的DOM元素 需要持续监听
      const pdpInfoContainer = document.querySelector('.section-v5-main-product') || document.querySelector('.product-info-container');

      // 该组件需要持续监听
      const v5Accordion = document.querySelector('.section-v5-accordion');

      if (pdpInfoContainer || v5Accordion) {
        // 创建防抖函数来限制refresh频率
        const debouncedRefresh = window.throttle(() => {
          if (self.v5ScrollProductFeatures1Trigger && typeof self.v5ScrollProductFeatures1Trigger.refresh === 'function') {
            self.v5ScrollProductFeatures1Trigger.refresh();
          }
          // 观察到变更后，启动/重置空闲期清理计时器
          // if(pdpInfoContainer){
          //   scheduleIdleCleanup();
          // }
        }, 100); // 100ms内最多执行一次

        // 创建ResizeObserver实例
        const observer = new ResizeObserver((entries) => {
          // 检查是否有实际的尺寸变化
          for (let entry of entries) {
            const { height } = entry.contentRect;
            // 只有当尺寸发生实际变化时才触发刷新
            if (height > 0) {
              debouncedRefresh();
              break;
            }
          }
        });

        // 在一段"空闲期"后自动清理，避免过早地 load 时断开监听
        let resizeIdleTimer = null;
        const scheduleIdleCleanup = () => {
          if (resizeIdleTimer) clearTimeout(resizeIdleTimer);
          resizeIdleTimer = setTimeout(() => {
            // 橱窗稳定，卸载监听
            cleanupObserver();
          }, 120000); // 2min，根据需要调整空闲期时长
        };

        // 开始观察元素尺寸变化
        [pdpInfoContainer, v5Accordion].forEach(element => {
          if (element) {
            observer.observe(element);
          }
        });

        // 断开观察
        const cleanupObserver = () => {
          if (observer) {
            observer.disconnect();
          }
          if (resizeIdleTimer) {
            clearTimeout(resizeIdleTimer);
            resizeIdleTimer = null;
          }
        };

        // 在页面隐藏或离开时清理，避免遗漏 load 之后生成的 DOM
        window.addEventListener('pagehide', cleanupObserver);
        document.addEventListener('visibilitychange', function () {
          if (document.visibilityState === 'hidden') cleanupObserver();
        });

        // 清理保障：当组件卸载时也应该断开观察
        if (window.Shopify && window.Shopify.designMode && this.section) {
          const parentSection = this.section.closest('.shopify-section');
          if (parentSection) {
            parentSection.addEventListener('section:unload', cleanupObserver);
          }
        }
      }
    }

    // 滚动动画
    scrollTimeLine() {
      if (!window._scrollTriggerRegistered) {
        window.gsap.registerPlugin(window.ScrollTrigger);
        window._scrollTriggerRegistered = true;
      }

      const self = this;
      let topH = '4.1666667vw';
      const productTabsBox = document.querySelector('.product-tabs-box,.section-navigation');
      if (productTabsBox) {
        topH = productTabsBox.offsetHeight + 'px';
      } else {
        const header = document.querySelector('jky-header,header-v5');
        topH = header.offsetHeight + 'px';
      }

      let tl;
      // 储存实例动画已经进行了多长的时间
      const time = tl ? tl.time() : 0;
      if (tl) {
        tl.kill();
      }

      tl = window.gsap.timeline({ paused: true });
      self.v5ScrollProductFeatures1Trigger = window.ScrollTrigger.create({
        trigger: this.sectionId,
        pin: true, // 将触发元素固定，在激活时
        start: `top ${topH}`, // 当触发元素的顶部碰到视口顶部时
        end: `bottom 25%`, // 在起始位置滚动 xxx 后结束
        scrub: 2, // 平滑擦洗，需要2秒钟来“赶上”滚动条
        smoothChildTiming: true,
        // markers: true,
        snap:[0,0.3,0.6,0.9,1],
        animation: tl,
      });

      tl.addLabel('start')
        .to('.v5-scroll-product-features-1 .title1', {
          y: '-360px',
          ease: 'power3.inOut',
          duration: 0.3,
        })
        .to(
          '.v5-scroll-product-features-1 .scroll-img-1',
          {
            y: '-100%',
            ease: 'power3.inOut',
            visibility: 'visible',
            duration: 0.3,
          },
          '<'
        )
        .addLabel('Screen3')
        .to(
          '.v5-scroll-product-features-1 .scroll-img-1',
          {
            opacity: 0,
            ease: 'power3.inOut',
            duration: 0.1,
          },
          'Screen3'
        )
        .to(
          '.v5-scroll-product-features-1 .scroll-img-2',
          {
            opacity: 1,
            ease: 'power3.inOut',
            duration: 0.3,
          },
          'Screen3'
        )
        .addLabel('Screen4')
        .to(
          '.v5-scroll-product-features-1 .scroll-img-2',
          {
            opacity: 0,
            ease: 'power3.in',
            duration: 0.1,
          },
          'Screen4'
        )
        .to(
          '.v5-scroll-product-features-1 .product-img',
          {
            x: '38.88889vw',
            scale: 1.1,
            ease: 'power3.in',
            duration: 0.3,
          },
          'Screen4'
        )
        .to(
          '.v5-scroll-product-features-1 .content-box',
          {
            opacity: 1,
            ease: 'power3.inOut',
            duration: 0.3,
          },
          'Screen4'
        )
        .to(
          '.v5-scroll-product-features-1 .content-box',
          {
            visibility: 'visible',
            ease: 'power3.inOut',
            duration: 0.1,
          }
        )
        .addLabel('end');
      tl.time(time);
    }
  }
  new V5ScrollProductFeatures1();
});